{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "General cap: reopen at 25% / AUD 6m."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Basket and de minimis: reset to AUD 50,000 tipping basket and AUD 5,000 de minimis."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "General time limit: 24 months. Do not accept 18 months without Amelia Frost's written approval."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Fundamental/title claims: separate regime, 100% cap, at least 6 years, outside basket, de minimis and knowledge bar."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Fraud, wilful concealment and deliberate misconduct: carve out of all caps, baskets, time limits, exclusive remedies and non-reliance"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Disclosure: reject general data-room, public-register and deemed disclosure (DL 1.1, 1.2; Sch 7). Require specific fair disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete clause 8.3's blanket buyer-knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Bluefen: require effective consent and evidence of the clause 11.3 conditions before Completion. Delete consent-on-delivery and the reasonable-endeavours standard."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Riverlark: require current payout, direct repayment from Completion funds and effective security releases."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Bonuses: add AUD 420,000 plus quantified on-costs as a specific funds flow line, or make them seller-funded."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Ironquay: broaden the indemnity beyond the SOW3 payment and preserve the SOW3 cure."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Export/privacy: preserve logs, require the investigation and regular updates, and do not accept \"not material\"."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Sandbar renewals (AUD 330,000): request evidence on unavoidability, termination rights and accrual. No automatic Debt classification or price deduction."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Delete the time-limit sweep. Keep categories separate."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Title: require independent title, ownership, encumbrance and authority evidence. DD-012 alone is not sufficient."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax and IP: keep open. Do not accept \"settled under the general regime\" and do not assume unlimited liability or resolution."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

